// privada/texto.js
function escapar(texto) {
  return texto.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
var negrito = (texto) => texto.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
var LIGACAO = /\[([^\]\n]+)\]\((https?:\/\/[^\s()"<>]+)\)/g;
var emLinha = (texto) => negrito(texto).replace(
  LIGACAO,
  '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>'
);
var LINHA_DA_TABELA = /^\s*\|.*\|\s*$/;
var SEPARADOR = /^\s*\|(\s*:?-{2,}:?\s*\|)+\s*$/;
function celulas(linha2) {
  return linha2.trim().slice(1, -1).split("|").map((celula) => emLinha(celula.trim()));
}
function tabela(cabecalho, corpo) {
  const linha2 = (etiqueta, valores) => `<tr>${valores.map((v2) => `<${etiqueta}>${v2}</${etiqueta}>`).join("")}</tr>`;
  return `<div class="tabela"><table><thead>${linha2("th", cabecalho)}</thead><tbody>${corpo.map((valores) => linha2("td", valores)).join("")}</tbody></table></div>`;
}
function formatar(texto) {
  const linhas = escapar(texto).split("\n");
  let html = "";
  let anteriorETexto = false;
  for (let i2 = 0; i2 < linhas.length; i2++) {
    if (LINHA_DA_TABELA.test(linhas[i2]) && SEPARADOR.test(linhas[i2 + 1] || "")) {
      const cabecalho = celulas(linhas[i2]);
      const corpo = [];
      for (i2 += 2; i2 < linhas.length && LINHA_DA_TABELA.test(linhas[i2]); i2++) {
        corpo.push(celulas(linhas[i2]));
      }
      i2--;
      html += tabela(cabecalho, corpo);
      anteriorETexto = false;
      continue;
    }
    html += (anteriorETexto ? "\n" : "") + emLinha(linhas[i2].replace(/^#{1,6}\s+(.+)$/, "<strong>$1</strong>"));
    anteriorETexto = true;
  }
  return html;
}

